mapper.select:
SELECT r.report_id,r.user_id,r.story_id,r.comment_id,r.reason,r.status,r.create_time,u.nickname AS reporter_name,s.title AS story_title
FROM report r JOIN `user` u ON r.user_id=u.user_id JOIN story s ON r.story_id=s.story_id
WHERE r.status=0 ORDER BY r.create_time DESC LIMIT #{limit}
